    Source2017 = Csv.Document(File.Contents("/path/to/data/raw/2017_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2018 = Csv.Document(File.Contents("/path/to/data/raw/2018_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2019 = Csv.Document(File.Contents("/path/to/data/raw/2019_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2020 = Csv.Document(File.Contents("/path/to/data/raw/2020_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2021 = Csv.Document(File.Contents("/path/to/data/raw/2021_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2022 = Csv.Document(File.Contents("/path/to/data/raw/2022_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2023 = Csv.Document(File.Contents("/path/to/data/raw/2023_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2024 = Csv.Document(File.Contents("/path/to/data/raw/2024_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Source2025 = Csv.Document(File.Contents("/path/to/data/raw/2025_Exports_HS10.csv"), [Delimiter=",", Encoding=65001]),
    Headers2015 = Table.PromoteHeaders(Source2015, [PromoteAllScalars=true]),
    Headers2016 = Table.PromoteHeaders(Source2016, [PromoteAllScalars=true]),
    Headers2017 = Table.PromoteHeaders(Source2017, [PromoteAllScalars=true]),
    Headers2018 = Table.PromoteHeaders(Source2018, [PromoteAllScalars=true]),
    Headers2019 = Table.PromoteHeaders(Source2019, [PromoteAllScalars=true]),
    Headers2020 = Table.PromoteHeaders(Source2020, [PromoteAllScalars=true]),
    Headers2021 = Table.PromoteHeaders(Source2021, [PromoteAllScalars=true]),
    Headers2022 = Table.PromoteHeaders(Source2022, [PromoteAllScalars=true]),
    Headers2023 = Table.PromoteHeaders(Source2023, [PromoteAllScalars=true]),
    Headers2024 = Table.PromoteHeaders(Source2024, [PromoteAllScalars=true]),
    Headers2025 = Table.PromoteHeaders(Source2025, [PromoteAllScalars=true]),
    Filter2015 = Table.SelectRows(Headers2015, each [hs] = "0402210019"),
    Filter2016 = Table.SelectRows(Headers2016, each [hs] = "0402210019"),
    Filter2017 = Table.SelectRows(Headers2017, each [hs] = "0402210019"),
    Filter2018 = Table.SelectRows(Headers2018, each [hs] = "0402210019"),
    Filter2019 = Table.SelectRows(Headers2019, each [hs] = "0402210019"),
    Filter2020 = Table.SelectRows(Headers2020, each [hs] = "0402210019"),
