    Filter2022 = Table.SelectRows(Headers2022, each [hs] = "0402210019"),
    Filter2023 = Table.SelectRows(Headers2023, each [hs] = "0402210019"),
    Filter2024 = Table.SelectRows(Headers2024, each [hs] = "0402210019"),
    Filter2025 = Table.SelectRows(Headers2025, each [hs] = "0402210019"),
    Combined = Table.Combine({Filter2015, Filter2016, Filter2017, Filter2018, Filter2019, Filter2020, Filter2021, Filter2022, Filter2023, Filter2024, Filter2025}),
    Selected = Table.SelectColumns(Combined, {"month","hs","uom","status","Export_Qty","Re_export_Qty","total_export_qty"}),
    Typed = Table.TransformColumnTypes(Selected, {{"month", type text},{"hs", type text},{"uom", type text},{"status", type text},{"Export_Qty", Int64.Type},{"Re_export_Qty", Int64.Type},{"total_export_qty", Int64.Type}}, "en-NZ"),
    AddMonth = Table.AddColumn(Typed, "Month", each #date(Number.FromText(Text.Start([month], 4)), Number.FromText(Text.End([month], 2)), 1), type date),
    InvalidRows = Table.SelectRows(AddMonth, each [uom] <> "KGM" or [status] <> "Final" or [Export_Qty] = null or [Re_export_Qty] = null or [total_export_qty] = null or [Export_Qty] <= 0 or [Re_export_Qty] < 0 or [Export_Qty] + [Re_export_Qty] <> [total_export_qty] or [Month] < #date(2015, 1, 1) or [Month] > #date(2025, 12, 1)),
    Validated = if Table.RowCount(InvalidRows) = 0 and Table.RowCount(AddMonth) = 132 and List.Count(List.Distinct(AddMonth[Month])) = 132 then AddMonth else error "Export data failed validation.",
    Renamed = Table.RenameColumns(Validated, {{"Export_Qty","Domestic WMP Exports kg"},{"Re_export_Qty","Re-exports kg"},{"total_export_qty","Total WMP Exports kg"}}),
    FinalColumns = Table.SelectColumns(Renamed, {"Month","hs","uom","status","Domestic WMP Exports kg","Re-exports kg","Total WMP Exports kg"}),
    Output = Table.Sort(FinalColumns, {{"Month", Order.Ascending}})
in
    Output
